args.command:
pid=$(pgrep -f 'openclaw/dist/index.js gateway --port 18789' | head -n1 || true); if [ -z "$pid" ]; then echo GATEWAY_PID=NONE; exit 0; fi; python3 - "$pid" <<'PY'
import sys
pid=sys.argv[1]
raw=open(f'/proc/{pid}/environ','rb').read().split(b'\0')
want={'HOME','OPENCLAW_HOME','OPENCLAW_CONFIG_PATH','OPENCLAW_STATE_DIR','OPENCLAW_PROFILE','XDG_CONFIG_HOME','PWD','USER','LOGNAME'}
vals={}
for item in raw:
 if b'=' not in item: continue
 k,v=item.split(b'=',1); k=k.decode(errors='replace')
 if k in want: vals[k]=v.decode(errors='replace')
for k in sorted(want):
 print(k+'='+vals.get(k,'<UNSET>'))
PY
